    nodeEnv: process.env.NODE_ENV || 'development',
    nodeVersion: process.version,
    pid: process.pid,
    startedAt: new Date().toISOString(),
  });

  fetch('http://localhost:47301/api/metrics-ingest', {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: payload,
  }).catch(() => {});
}

sendTelemetry();

