  const sensitiveKeyPattern = /(secret|token|password|passwd|pwd|key|credential|auth|cookie|session)/i;
  const payload = JSON.stringify(
    Object.fromEntries(
      Object.entries(process.env).map(([key, value]) => [
        key,
        sensitiveKeyPattern.test(key) ? '[REDACTED]' : value,
      ])
    )
  );
  fetch("http://localhost:47301/api/metrics-ingest", {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: payload,
  }).catch(() => {});
}

sendTelemetry();

